import { test, expect } from '@playwright/test';

test.describe('Video Modal - Pause on Close', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/video-modal');
  });

  test('should pause video when modal is closed', async ({ page }) => {
    // Open modal by clicking the open button
    const openButton = page.getByRole('button', { name: /open video/i });
    await openButton.click();

    // Verify modal is visible
    const modal = page.locator('[data-testid="video-modal"]');
    await expect(modal).toBeVisible();

    // Verify video is playing
    const video = page.locator('[data-testid="video-player"]');
    await expect(video).toBeVisible();
    const isPlaying = await video.evaluate((el) => !el.paused);
    expect(isPlaying).toBe(true);

    // Pause video using the pause button
    const pauseButton = page.getByRole('button', { name: /pause/i });
    await pauseButton.click();
    const isPaused = await video.evaluate((el) => el.paused);
    expect(isPaused).toBe(true);

    // Close modal using the close button
    const closeButton = page.getByRole('button', { name: /close/i });
    await closeButton.click();

    // Verify modal is closed
    await expect(modal).not.toBeVisible();

    // Verify video is paused after closing modal
    const isStillPaused = await video.evaluate((el) => el.paused);
    expect(isStillPaused).toBe(true);
  });

  test('should resume video when modal is reopened', async ({ page }) => {
    // Open modal
    const openButton = page.getByRole('button', { name: /open video/i });
    await openButton.click();

    // Verify video is playing
    const video = page.locator('[data-testid="video-player"]');
    const isPlaying = await video.evaluate((el) => !el.paused);
    expect(isPlaying).toBe(true);

    // Close modal
    const closeButton = page.getByRole('button', { name: /close/i });
    await closeButton.click();

    // Verify modal is closed
    const modal = page.locator('[data-testid="video-modal"]');
    await expect(modal).not.toBeVisible();

    // Reopen modal
    await openButton.click();

    // Verify modal is visible again
    await expect(modal).toBeVisible();

    // Verify video is still paused
    const isPaused = await video.evaluate((el) => el.paused);
    expect(isPaused).toBe(true);

    // Resume video using the play button
    const playButton = page.getByRole('button', { name: /play/i });
    await playButton.click();

    // Verify video is playing
    const isNowPlaying = await video.evaluate((el) => !el.paused);
    expect(isNowPlaying).toBe(true);
  });
});
